package com.fullstack.exp232.controller;
import com.fullstack.exp232.model.*;import com.fullstack.exp232.security.AesEncryptionService;import com.fullstack.exp232.service.TokenService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController public class SecurityController {private final TokenService t;private final AesEncryptionService aes;public SecurityController(TokenService t,AesEncryptionService aes){this.t=t;this.aes=aes;}@PostMapping("/auth/login")public ResponseEntity<?> login(@RequestBody LoginRequest r){boolean ok=("user".equals(r.username())&&"user123".equals(r.password()))||("admin".equals(r.username())&&"admin123".equals(r.password()));return ok?ResponseEntity.ok(t.issue(r.username())):ResponseEntity.status(401).body("Invalid username or password");}@PostMapping("/auth/refresh")public ResponseEntity<?> refresh(@RequestBody Map<String,String> b){try{return ResponseEntity.ok(t.refresh(b.get("refreshToken")));}catch(Exception e){return ResponseEntity.status(401).body("Invalid or expired refresh token");}}@PostMapping("/secure/store-credential")public Map<String,String> store(@RequestParam String provider,@RequestParam String credential){return Map.of("message","Credential encrypted and stored","encryptedValue",t.store(provider,credential));}@GetMapping("/secure/read-credential")public Map<String,String> read(@RequestParam String provider){String e=t.read(provider);return Map.of("encryptedValue",e,"decryptedValue",aes.decrypt(e));}}
